      ExecStart = "${apache}/bin/httpd -f /etc/apache2/apache2.conf -DFOREGROUND";
      ExecReload = "${apache}/bin/httpd -f /etc/apache2/apache2.conf -t && ${apache}/bin/httpd -f /etc/apache2/apache2.conf -k graceful";
