    enable = true;
    package = pkgs.mariadb;
    settings.mysqld = {
      bind-address = "127.0.0.1";
      character-set-server = "utf8mb4";
      collation-server = "utf8mb4_general_ci";
    };
    initialScript = mysqlInit;
  };

  services.postgresql = {
    enable = true;
    package = pgPackage;
    settings = {
      listen_addresses = lib.mkForce "127.0.0.1";
      password_encryption = "scram-sha-256";
      timezone = "Etc/UTC";
    };
    authentication = lib.mkForce ''
      local all all peer
      host all all 127.0.0.1/32 scram-sha-256
      host all all ::1/128 scram-sha-256
    '';
    initialScript = initSql;
  };

  services.memcached = {
    enable = true;
    listen = "127.0.0.1";
    port = 11211;
    maxMemory = 32;
    user = "memcache";
    extraOptions = [ "-U" "0" ];
  };

  security.sudo.extraConfig = ''
    Defaults	env_reset
    Defaults	mail_badpass
    root	ALL=(ALL:ALL) ALL
    %admin ALL=(ALL) ALL
    %sudo	ALL=(ALL:ALL) ALL
    amber ALL=(:adm) NOPASSWD: /bin/cat /var/log/web/amber-access.log, /bin/cat /var/log/web/amber-error.log
    cobalt ALL=(:adm) NOPASSWD: /bin/cat /var/log/web/cobalt-access.log, /bin/cat /var/log/web/cobalt-error.log
  '';

  services.openssh = {
    settings = {
      PasswordAuthentication = false;
      KbdInteractiveAuthentication = false;
      X11Forwarding = true;
      AcceptEnv = [ "LANG" "LC_*" ];
    };
  };

  system.stateVersion = "26.05";
}

